example.en:
```ts
type Layer = { id: string; opener: HTMLElement | null }
const stack: Layer[] = []
let scrollLocks = 0
function openModal(id: string, opener: HTMLElement | null) {
  stack.push({ id, opener })
  if (++scrollLocks === 1) document.body.style.overflow = 'hidden'
}
function closeTop() {
  const top = stack.pop()
  if (--scrollLocks === 0) document.body.style.overflow = ''
  top?.opener?.focus() // parent opener, not the original page, while stack remains
}
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && stack.length) closeTop() // one listener; top only
})
function trapOwner() { return stack.at(-1)?.id ?? null }
```

One listener, reference-counted scroll, restore to the previous opener. The Tab cycle still lives inside the top dialog only.

