type Layer = { id: string; opener: HTMLElement | null }
const stack: Layer[] = []
let scrollLocks = 0
function openModal(id: string, opener: HTMLElement | null) {
  stack.push({ id, opener })
  if (++scrollLocks === 1) document.body.style.overflow = 'hidden'
}
function closeTop() {
  const top = stack.pop()
  if (--scrollLocks === 0) document.body.style.overflow = ''
  top?.opener?.focus() // opener của parent, không phải trang gốc, khi stack còn
}
window.addEventListener('keydown', (e) => {
  if (e.key === 'Escape' && stack.length) closeTop() // một listener; chỉ layer trên
})
function trapOwner() { return stack.at(-1)?.id ?? null }
```

Một listener, scroll đếm tham chiếu, restore về opener trước. Vòng Tab vẫn sống chỉ trong dialog trên cùng.

example.en:
```ts
function trap(dialog: HTMLElement, onClose: () => void) {
  const prev = document.activeElement as HTMLElement | null
  const tabbable = () =>
    [...dialog.querySelectorAll<HTMLElement>(
      'a[href],button:not([disabled]),input:not([disabled]),[tabindex]:not([tabindex="-1"])',
    )].filter((el) => !el.hasAttribute('hidden') && el.offsetParent !== null)
  const key = (e: KeyboardEvent) => {
    if (e.key === 'Escape') { onClose(); return }
    if (e.key !== 'Tab') return
    const list = tabbable()
    const first = list[0], last = list[list.length - 1]
    if (e.shiftKey && document.activeElement === first) { e.preventDefault(); last?.focus() }
    else if (!e.shiftKey && document.activeElement === last) { e.preventDefault(); first?.focus() }
  }
  dialog.addEventListener('keydown', key)
  tabbable()[0]?.focus()
  return () => { dialog.removeEventListener('keydown', key); prev?.focus() }
}
```

Save, cycle, restore. Nested stacks are not this function — they decide **which** dialog owns `keydown`.

