```ts
async function login(email: string, password: string) {
  const { accessToken } = await api.post('/auth/login', { email, password })
  tokenMemory.set(accessToken) // never localStorage
  return api.get('/me')
}
async function logoutAllTabs() {
  tokenMemory.set(null)
  new BroadcastChannel('auth').postMessage({ type: 'logout' })
  await api.post('/auth/logout') // server revokes the refresh family
}
// Cookie: Set-Cookie refresh=...; HttpOnly; Secure; SameSite=Lax
// Route middleware that only hides UI is not authz.
```

The refresh cookie is set by the API, not by JS. Access stays in memory. Logout revokes on the server and tells sibling tabs.

