```tsx
class ChartBoundary extends Component<{ children: ReactNode }, { err: Error | null }> {
  state = { err: null as Error | null }
  static getDerivedStateFromError(err: Error) { return { err } }
  render() {
    if (this.state.err) return <p>chart failed</p>
    return this.props.children
  }
}
function Chart() { throw new Error('render') } // caught
function Buy() {
  function onClick() { throw new Error('click') } // NOT caught
  return <button onClick={onClick}>buy</button>
}
// wrap <Chart /> not the whole app — chrome must survive
```

The render throw inside `Chart` paints the fallback. The click throw never reaches the boundary; wrap that path in `try/catch` or lift it into render state.

