    return this.props.children
  }
}
function Chart() { throw new Error('render') } // bắt được
function Buy() {
  function onClick() { throw new Error('click') } // KHÔNG bắt được
  return <button onClick={onClick}>buy</button>
}
// bọc <Chart />, không bọc cả app: chrome phải còn
```

Throw lúc render trong `Chart` vẽ fallback. Throw lúc click không bao giờ tới boundary; bọc đường đó trong `try/catch` hoặc đưa lên state lúc render.

example.en:
```ts
function makeCounter(start = 0) {
  let n = start
  return () => ++n
}
const a = makeCounter()
a() // 1
a() // 2

function debounceLatest<T extends unknown[]>(fn: (...args: T) => void, ms: number) {
  let last: T
  let timer = 0
  return (...args: T) => {
    last = args // not the args from call #1
    clearTimeout(timer)
    timer = window.setTimeout(() => fn(...last), ms)
  }
}
```

The counter closes over `n` — one binding, not a snapshot. `debounceLatest` stores `last` on the wrapper so the timeout always fires with the newest args. A timeout that closed over call-#1 `args` is the stale-closure bug.

example.vi:
```ts
function makeCounter(start = 0) {
  let n = start
  return () => ++n
}
const a = makeCounter()
a() // 1
a() // 2

function debounceLatest<T extends unknown[]>(fn: (...args: T) => void, ms: number) {
  let last: T
  let timer = 0
  return (...args: T) => {
    last = args // không phải args lần gọi #1
    clearTimeout(timer)
    timer = window.setTimeout(() => fn(...last), ms)
  }
}
```

Bộ đếm close over `n`: một binding, không phải snapshot. `debounceLatest` lưu `last` trên wrapper nên timeout luôn chạy với args mới nhất. Timeout close over `args` lần gọi #1 chính là bug stale closure.

example.en:
```ts
const user = {
  name: 'Ada',
  greet() {
    return this.name
  },
}
user.greet()                 // 'Ada' — method call
const lost = user.greet
lost()                       // TypeError / undefined — default this
user.greet.call({ name: 'Lin' }) // 'Lin'
const bound = user.greet.bind(user)
bound()                      // 'Ada' — same reference to remove later

// Vue Options: function, not arrow
methods: {
  onSubmit() { this.$emit('save') },
}
```

Method call binds the receiver. Extracting the function loses `this`. `bind` fixes it and gives you an identity you can remove. An arrow in Options `methods` would capture module `this`.

example.vi:
```ts
const user = {
  name: 'Ada',
  greet() {
    return this.name
  },
}
user.greet()                 // 'Ada': gọi method
const lost = user.greet
lost()                       // TypeError / undefined: this mặc định
user.greet.call({ name: 'Lin' }) // 'Lin'
const bound = user.greet.bind(user)
bound()                      // 'Ada': cùng reference để gỡ sau

// Vue Options: function, không phải arrow
methods: {
  onSubmit() { this.$emit('save') },
}
```

Gọi method gắn receiver. Tách hàm làm mất `this`. `bind` sửa và cho bạn identity có thể gỡ. Arrow trong `methods` Options sẽ bắt `this` của module.

