```ts
function upsertById<T extends { id: string }>(rows: T[], row: T): T[] {
  return [...rows.filter((r) => r.id !== row.id), row]
}

const users = upsertById(
  [{ id: '1', name: 'Ada' }],
  { id: '1', name: 'Ada Lovelace' },
) // T inferred as { id: string; name: string }

// callers writing <User> every time means inference failed
function wrap<T>(x: T): T {
  return x // delete <T> — T is not used
}
```

`upsertById` constrains `id` because the body needs it, so T is inferred from the array. `wrap` is generic for show.

