```ts
type DeepReadonly<T> = T extends (...args: never[]) => unknown
  ? T
  : T extends object
    ? { readonly [K in keyof T]: DeepReadonly<T[K]> }
    : T

type Profile = {
  name: string
  save: () => void
  address: { city: string }
}
type Frozen = DeepReadonly<Profile>
// Frozen['name'] is readonly string
// Frozen['save'] stays callable
// Frozen['address']['city'] is readonly

type ToArray<T> = T extends unknown ? T[] : never
type A = ToArray<string | number> // string[] | number[]
```

Functions are excluded so `save` stays callable. Naked T in `ToArray` distributes.

