```ts
function isAbortError(e: unknown): e is DOMException {
  return e instanceof DOMException && e.name === 'AbortError'
}

function assertNever(x: never): never {
  throw new Error('unreachable: ' + String(x))
}

type Job = { status: 'idle' } | { status: 'run' } | { status: 'done'; id: string }

function label(job: Job) {
  switch (job.status) {
    case 'idle':
      return '…'
    case 'run':
      return 'running'
    case 'done':
      return job.id
    default:
      return assertNever(job)
  }
}
```

`isAbortError` checks name, not only instanceof. `assertNever` makes a new status a compile error.

