```ts
const bucket = new WeakMap<object, Map<string, Set<() => void>>>()
function track(t: object, key: string) {
  if (!active) return
  let keys = bucket.get(t) ?? new Map()
  bucket.set(t, keys)
  let fx = keys.get(key) ?? new Set()
  keys.set(key, fx)
  fx.add(active)
}
function trigger(t: object, key: string) {
  bucket.get(t)?.get(key)?.forEach((fn) => fn())
}
let active: (() => void) | null = null
// Vue 3 does this inside a Proxy get/set — a missed read never tracks
```

A get while `active` is set records the effect. A later set re-runs only that set. Destructuring before the effect is a missed read.

