```ts
export function useFetch<T>(url: () => string, fetchImpl = fetch) {
  const data = ref<T | null>(null)
  const error = ref<unknown>(null)
  watchEffect((onCleanup) => {
    const ac = new AbortController()
    onCleanup(() => ac.abort())
    fetchImpl(url(), { signal: ac.signal })
      .then((r) => r.json())
      .then((j) => { data.value = j })
      .catch((e) => { if (e.name !== 'AbortError') error.value = e })
  })
  onScopeDispose(() => { /* extra listeners would stop here */ })
  return { data, error }
}
```

The getter is tracked. Re-run aborts the previous fetch. `onScopeDispose` stops extras when the owner unmounts. Tests pass a fake `fetchImpl`.

