function Parent() {
  const [q, setQ] = useState('')
  const [n, setN] = useState(0)
  return (
    <>
      <input value={q} onChange={(e) => setQ(e.target.value)} />
      <Heavy rows={ROWS} /> {/* re-renders on every keystroke */}
      <button onClick={() => setN(n + 1)}>{n}</button>
    </>
  )
}
const Heavy = memo(function Heavy({ rows }: { rows: Row[] }) {
  renderCount++ // still 1+ per parent run unless Parent stops passing new rows
  return <ul>{rows.length}</ul>
})
// fix: move the input into its own component so Parent (and Heavy) stay still
```

Each keystroke re-runs `Parent`, so `Heavy` runs unless it bails out **and** `rows` is a stable identity. Vue would only re-run the input’s effect. Count `renderCount` in the Profiler to prove it.

