function Panel({ user }: { user: User | null }) {
  const [open, setOpen] = useState(false)
  // ❌ if (!user) return null  — this skip would shift the next slot
  useEffect(() => {
    if (!user) return
    const off = subscribe(user.id)
    return off
  }, [user])
  if (!user) return null // ✅ after every hook
  return <button onClick={() => setOpen(!open)}>{open ? 'hide' : 'show'}</button>
}
// eslint-plugin-react-hooks flags hooks after a conditional return
```

Slot 0 is always `open`. Slot 1 is always the effect. Moving the `user` check below those calls keeps order stable; putting it above would attach `open` to the wrong hook on the next paint.

