import { NextResponse } from 'next/server'
import type { NextRequest } from 'next/server'

export function middleware(req: NextRequest) {
  const session = req.cookies.get('session')?.value
  if (!session && req.nextUrl.pathname.startsWith('/admin')) {
    const url = req.nextUrl.clone()
    url.pathname = '/login'
    url.searchParams.set('next', req.nextUrl.pathname)
    return NextResponse.redirect(url) // UX gate — page still authorizes
  }
  return NextResponse.next()
}
export const config = { matcher: ['/admin/:path*'] } // skip static
// Nuxt analog: middleware/auth.ts (route) vs server/middleware (Nitro hop)
```

Middleware only redirects. The admin page still checks the session before it reads data. Nuxt route middleware is the page-level analog; Nitro middleware is the request-shaping analog.

