const b = rows.reduce<string[]>((acc, r) => {
  if (r.active) acc.push(r.name)
  return acc
}, [])
const c: string[] = []
rows.forEach((r) => {
  if (r.active) c.push(r.name) // dựng lại map+filter bằng side effect
})
// a và b (nếu copy) là ['Ada']; c mutate c tại chỗ

// ❌ mutation
rows.sort((x, y) => x.name.localeCompare(y.name))
```

`filter`+`map` nói ý. `reduce` là một lượt khi bạn đã biết mình cần. `forEach`+`push` che việc bạn muốn `map`. `sort` mutate `rows`.

