```ts
function uiForStatus(status: number, body: { error?: { code: string; fields?: Record<string, string> } }) {
  if (status === 401) return { kind: "session" }
  if (status === 403) return { kind: "forbidden" }
  if (status === 422) return { kind: "fields", fields: body.error?.fields ?? {} }
  if (status === 429) return { kind: "backoff" }
  if (status >= 500) return { kind: "retry-if-idempotent" }
  return { kind: "unknown" }
}
// fetch("/x") 404 → ok=false, no throw. $fetch often throws.
// POST /pay retries only with the same Idempotency-Key.
```

Status chooses a screen. 422 paints fields from the envelope, not from the English message. 5xx does not auto-retry Pay.

