```tsx
function DragLabel() {
  const [label, setLabel] = useState('idle')
  const lastX = useRef(0) // does not re-render
  function onMove(e: PointerEvent) {
    lastX.current = e.clientX // 60/s — keep out of state
  }
  function onUp() {
    setLabel(`x=${lastX.current}`) // paint once
  }
  useEffect(() => {
    window.addEventListener('pointermove', onMove)
    window.addEventListener('pointerup', onUp)
    return () => {
      window.removeEventListener('pointermove', onMove)
      window.removeEventListener('pointerup', onUp)
    }
  }, [])
  return <p>{label}</p>
}
```

Moves write the ref and do not notify React. Mouseup copies into state so the label paints once. Vue `ref()` would have re-rendered on every move if you bound it in the template.

