```ts
function debounce<T extends (...args: unknown[]) => void>(fn: T, wait = 300) {
  let timer: ReturnType<typeof setTimeout> | null = null
  let lastArgs: Parameters<T> | null = null
  const wrapped = (...args: Parameters<T>) => {
    lastArgs = args
    if (timer) clearTimeout(timer)
    timer = setTimeout(() => {
      timer = null
      fn(...(lastArgs as Parameters<T>))
    }, wait)
  }
  wrapped.cancel = () => {
    if (timer) clearTimeout(timer)
    timer = null
  }
  wrapped.flush = () => {
    if (!timer || !lastArgs) return
    clearTimeout(timer)
    timer = null
    fn(...lastArgs)
  }
  return wrapped
}
```

`cancel` on unmount. `flush` on submit. The timeout always sees the newest `lastArgs`. Tests: rapid “ab”/“abc” → one call; cancel → none.

