```ts
function throttle<T extends (...args: unknown[]) => void>(fn: T, wait = 300) {
  let last = 0
  let timer: ReturnType<typeof setTimeout> | null = null
  let lastArgs: Parameters<T>
  return (...args: Parameters<T>) => {
    lastArgs = args
    const remaining = wait - (Date.now() - last)
    if (remaining <= 0) {
      if (timer) { clearTimeout(timer); timer = null }
      last = Date.now()
      fn(...args)
    } else if (!timer) {
      timer = setTimeout(() => {
        last = Date.now()
        timer = null
        fn(...lastArgs)
      }, remaining)
    }
  }
}
```

Leading fire, then a trailing fire with the newest args. Without the timer, the last scroll position is lost. Tests should include that last event.

