```ts
function promiseAll<T>(items: Array<T | PromiseLike<T>>): Promise<T[]> {
  return new Promise((resolve, reject) => {
    if (items.length === 0) { resolve([]); return }
    const results = new Array<T>(items.length)
    let done = 0
    let settled = false
    items.forEach((item, i) => {
      Promise.resolve(item).then((value) => {
        if (settled) return
        results[i] = value
        done += 1
        if (done === items.length) resolve(results)
      }, (err) => {
        if (settled) return
        settled = true
        reject(err)
      })
    })
  })
}
```

Results go in by index. Empty resolves immediately. The first rejection wins; later completions are ignored.

