```ts
function deepClone<T>(value: T, seen = new WeakMap<object, unknown>()): T {
  if (typeof structuredClone === 'function') {
    try { return structuredClone(value) } catch { /* functions / DOM / proxy */ }
  }
  if (value === null || typeof value !== 'object') return value
  const obj = value as object
  if (seen.has(obj)) return seen.get(obj) as T
  if (Array.isArray(value)) {
    const out: unknown[] = []
    seen.set(obj, out)
    for (const item of value) out.push(deepClone(item, seen))
    return out as T
  }
  const out: Record<string, unknown> = {}
  seen.set(obj, out)
  for (const [k, v] of Object.entries(obj)) out[k] = deepClone(v, seen)
  return out as T
}
```

Try `structuredClone` first. The `WeakMap` is the cycle case the JSON one-liner never handles. Vue proxies belong in the `catch` — `toRaw` before calling.

