```ts
class EventEmitter<T = unknown> {
  private events = new Map<string, Set<(payload: T) => void>>()
  on(event: string, fn: (payload: T) => void) {
    const set = this.events.get(event) ?? new Set()
    set.add(fn)
    this.events.set(event, set)
    return () => this.off(event, fn)
  }
  off(event: string, fn: (payload: T) => void) {
    const set = this.events.get(event)
    if (!set) return
    set.delete(fn)
    if (set.size === 0) this.events.delete(event)
  }
  once(event: string, fn: (payload: T) => void) {
    const wrap = (p: T) => { this.off(event, wrap); fn(p) }
    return this.on(event, wrap)
  }
  emit(event: string, payload: T) {
    const set = this.events.get(event)
    if (!set) return
    for (const fn of [...set]) fn(payload) // snapshot
  }
}
```

`[...set]` is the mid-emit safety. `once` removes before `fn`. Empty keys are deleted so the Map does not leak event names.

