let refreshInFlight: Promise<string> | null = null
async function refreshAccess(): Promise<string> {
  if (!refreshInFlight) {
    refreshInFlight = api.post('/auth/refresh').then((r) => {
      tokenMemory.set(r.accessToken)
      return r.accessToken
    }).finally(() => { refreshInFlight = null })
  }
  return refreshInFlight
}
api.onError(async (err, req) => {
  if (err.status !== 401 || req.url.includes('/auth/refresh') || req.retried) throw err
  const token = await refreshAccess()
  return api.retry(req, { retried: true, token })
})
```

Ten 401s share one POST. A 401 from refresh must not enter this branch or logout loops.

